import requests


class Tools:
    def __init__(self):
        self.citation = False
        self.backend_uri = "http://172.17.0.1:8000"

    async def get_defect_in_last_hour(
        self, __user__: dict = {}, __event_emitter__=None
    ) -> str:
        """
        This function makes an HTTP GET request to the backend to retrieve defects that occurred in
        the last hour. The data returned includes the number of defects and an image related to
        the defects in the last hour.
        """
        if __event_emitter__:
            await __event_emitter__(
                {
                    "type": "status",
                    "data": {
                        "description": "Retrieving defects data in last hour from database ...",
                        "done": False,
                    },
                }
            )

        response = requests.get(f"{self.backend_uri}/defects_last_hour")
        if response.status_code == 200:
            results = response.json()

            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": f"Getting image from: http://localhost:8000/{results['data']['chart_image_url']} ...",
                            "done": False,
                        },
                    }
                )
                await __event_emitter__(
                    {
                        "type": "message",
                        "data": {
                            "content": f"![](http://localhost:8000/{results['data']['chart_image_url']})"
                        },
                    }
                )
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": f"Successfully retrieved defects data in last one hour!",
                            "done": True,
                        },
                    }
                )
                return f"STRICTLY reply in the this format only: 'Number of defects found in last hour is {results['data']['number_defects']}"
        else:
            if __event_emitter__:
                await __event_emitter__(
                    {
                        "type": "status",
                        "data": {
                            "description": "Failed to retrieve data from database. Please retry again or contact admin for more info!",
                            "done": True,
                        },
                    }
                )
                return f"Failed to retrieve data from database. Please retry again or contact admin for more info!"

